# Generated by build.py from recipe.yml for recipe imap-append-and-flag-a-message. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'order.txt'), "From: shop@example.com`nTo: bob@example.com`nSubject: Order 1001 shipped`n`nYour order is on its way.`n")
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', 'imap://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -T order.txt imap://127.0.0.1:8080/INBOX --next -X "STORE 1 +FLAGS \Flagged" imap://127.0.0.1:8080/INBOX } finally { Stop-Process $server0 }
